-- As the instance owner: two tables with a DECFLOAT column the agent user may read, one left set integrity pending and one left REORG-pending, and the state SYSCAT.TABLES records for each.
CREATE TABLE APP.LIBREDB_PS_CHECK (ID INTEGER NOT NULL, C_DF DECFLOAT(16), CONSTRAINT LIBREDB_PS_CHECK_ID CHECK (ID > 0));
SET INTEGRITY FOR APP.LIBREDB_PS_CHECK OFF;
CREATE TABLE APP.LIBREDB_PS_REORG (ID INTEGER NOT NULL, C_DF DECFLOAT(34), C_GONE INTEGER);
ALTER TABLE APP.LIBREDB_PS_REORG DROP COLUMN C_GONE;
GRANT SELECT ON APP.LIBREDB_PS_CHECK TO USER AGENT_RO;
GRANT SELECT ON APP.LIBREDB_PS_REORG TO USER AGENT_RO;
SELECT VARCHAR(TABNAME, 18) AS TABNAME, STATUS, ACCESS_MODE FROM SYSCAT.TABLES WHERE TABSCHEMA = 'APP' AND TABNAME LIKE 'LIBREDB_PS_%' ORDER BY 1;
SELECT VARCHAR(TABNAME, 18) AS TABNAME, REORG_PENDING, VARCHAR(INPLACE_REORG_STATUS, 10) AS INPLACE, VARCHAR(LOAD_STATUS, 10) AS LOAD_STATUS FROM SYSIBMADM.ADMINTABINFO WHERE TABSCHEMA = 'APP' AND TABNAME LIKE 'LIBREDB_PS_%' ORDER BY 1;
